begin;
create extension if not exists pgcrypto;
create type public.restec_environment as enum ('sandbox','production');
create type public.outbox_status as enum ('pending','processing','delivered','dead_letter');
create table public.partners(id text primary key check(id~'^ptr_'),name text not null,status text not null default 'active',created_at timestamptz not null default now());
create table public.partner_users(id uuid primary key references auth.users(id) on delete restrict,partner_id text not null references public.partners(id) on delete restrict,role text not null check(role in('owner','admin','developer','viewer')),created_at timestamptz not null default now());
create table public.restaurants(id text primary key check(id~'^rst_'),partner_id text not null references public.partners(id) on delete restrict,name text not null,created_at timestamptz not null default now());
create table public.locations(id text primary key check(id~'^loc_'),restaurant_id text not null references public.restaurants(id) on delete restrict,environment public.restec_environment not null,name text not null,private_location_reference uuid not null,created_at timestamptz not null default now(),unique(id,environment));
create table public.api_keys(id uuid primary key default gen_random_uuid(),partner_id text not null references public.partners(id) on delete restrict,environment public.restec_environment not null,key_prefix text not null unique,key_hash text not null,status text not null check(status in('active','overlap','revoked')),created_at timestamptz not null default now(),last_used_at timestamptz,expires_at timestamptz,revoked_at timestamptz);
create table public.pos_connections(id text primary key check(id~'^con_'),partner_id text not null references public.partners(id) on delete restrict,location_id text not null references public.locations(id) on delete restrict,environment public.restec_environment not null,connector_type text not null,connector_version text not null,encrypted_configuration text not null,status text not null check(status in('active','disabled','error')),private_connection_reference uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(location_id,environment));
create table public.pos_tables(id text primary key check(id~'^tbl_'),location_id text not null references public.locations(id) on delete restrict,name text not null,created_at timestamptz not null default now());
create table public.table_mappings(id uuid primary key default gen_random_uuid(),connection_id text not null references public.pos_connections(id) on delete restrict,external_table_id text not null,restec_table_id text not null references public.pos_tables(id) on delete restrict,private_table_reference uuid not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(connection_id,external_table_id),unique(connection_id,restec_table_id));
create table public.bill_mappings(id uuid primary key default gen_random_uuid(),connection_id text not null references public.pos_connections(id) on delete restrict,external_bill_id text not null,public_restec_bill_id text not null check(public_restec_bill_id~'^bil_'),private_paely_bill_reference text not null,current_version integer not null check(current_version>0),last_request_hash text not null,payment_status text not null,reconciliation_status text not null default 'pending',public_state jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(connection_id,external_bill_id),unique(public_restec_bill_id));
create table public.external_payments(id uuid primary key default gen_random_uuid(),bill_mapping_id uuid not null references public.bill_mappings(id) on delete restrict,external_payment_id text not null,public_restec_payment_id text not null check(public_restec_payment_id~'^pay_'),request_hash text not null,amount integer not null check(amount>0),currency char(3) not null,status text not null,created_at timestamptz not null default now(),unique(bill_mapping_id,external_payment_id));
create table public.webhook_endpoints(id uuid primary key default gen_random_uuid(),connection_id text not null references public.pos_connections(id) on delete restrict,url text not null,encrypted_signing_secret text not null,status text not null check(status in('active','disabled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.idempotency_records(id uuid primary key default gen_random_uuid(),partner_id text not null references public.partners(id) on delete restrict,idempotency_key text not null,method text not null,path text not null,request_hash text not null,status text not null check(status in('processing','completed')),response_status integer,response_body jsonb,created_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '7 days',unique(partner_id,idempotency_key));
create table public.replay_records(request_id text primary key check(request_id~'^req_'),partner_id text not null references public.partners(id) on delete restrict,received_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '10 minutes');
create table public.paely_event_inbox(id uuid primary key default gen_random_uuid(),private_event_id text not null unique,event_type text not null,schema_version text not null,connection_id text not null references public.pos_connections(id) on delete restrict,request_hash text not null,payload jsonb not null,status text not null,received_at timestamptz not null default now(),processed_at timestamptz);
create table public.pos_outbox_events(id uuid primary key default gen_random_uuid(),public_event_id text not null unique check(public_event_id~'^evt_'),connection_id text not null references public.pos_connections(id) on delete restrict,event_type text not null,schema_version text not null,payload jsonb not null,deduplication_key text not null,status public.outbox_status not null default 'pending',attempt_count integer not null default 0,next_attempt_at timestamptz not null default now(),locked_at timestamptz,lock_expires_at timestamptz,delivered_at timestamptz,last_error_code text,created_at timestamptz not null default now(),unique(connection_id,deduplication_key));
create table public.webhook_delivery_attempts(id uuid primary key default gen_random_uuid(),outbox_event_id uuid not null references public.pos_outbox_events(id) on delete restrict,attempt_number integer not null,response_status integer,outcome text not null,error_code text,duration_ms integer not null,created_at timestamptz not null default now(),unique(outbox_event_id,attempt_number));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_type text not null,actor_id text,partner_id text references public.partners(id) on delete restrict,connection_id text references public.pos_connections(id) on delete restrict,request_id text,action text not null,result text not null,target_type text,target_id text,ip_hash text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index api_keys_auth_idx on public.api_keys(key_prefix,environment,status); create index idempotency_expiry_idx on public.idempotency_records(expires_at); create index replay_expiry_idx on public.replay_records(expires_at); create index bill_mapping_lookup_idx on public.bill_mappings(connection_id,external_bill_id); create index outbox_claim_idx on public.pos_outbox_events(status,next_attempt_at) where status in('pending','processing'); create index inbox_connection_idx on public.paely_event_inbox(connection_id,received_at); create index audit_partner_idx on public.audit_logs(partner_id,created_at desc);
alter table public.partners enable row level security; alter table public.partner_users enable row level security; alter table public.restaurants enable row level security; alter table public.locations enable row level security; alter table public.api_keys enable row level security; alter table public.pos_connections enable row level security; alter table public.pos_tables enable row level security; alter table public.table_mappings enable row level security; alter table public.bill_mappings enable row level security; alter table public.external_payments enable row level security; alter table public.webhook_endpoints enable row level security; alter table public.idempotency_records enable row level security; alter table public.replay_records enable row level security; alter table public.paely_event_inbox enable row level security; alter table public.pos_outbox_events enable row level security; alter table public.webhook_delivery_attempts enable row level security; alter table public.audit_logs enable row level security;
create policy partner_user_self on public.partner_users for select to authenticated using(id=auth.uid());
create or replace function public.accept_private_event(p_private_event_id text,p_event_type text,p_schema_version text,p_connection_id text,p_request_hash text,p_payload jsonb,p_public_event_id text,p_public_payload jsonb) returns table(accepted boolean,event_id text) language plpgsql security definer set search_path=public as $$ begin insert into paely_event_inbox(private_event_id,event_type,schema_version,connection_id,request_hash,payload,status,processed_at) values(p_private_event_id,p_event_type,p_schema_version,p_connection_id,p_request_hash,p_payload,'accepted',now()) on conflict(private_event_id) do nothing; if not found then return query select true,o.public_event_id from pos_outbox_events o join paely_event_inbox i on i.connection_id=o.connection_id where i.private_event_id=p_private_event_id order by o.created_at limit 1; return; end if; insert into pos_outbox_events(public_event_id,connection_id,event_type,schema_version,payload,deduplication_key) values(p_public_event_id,p_connection_id,p_event_type,p_schema_version,p_public_payload,p_private_event_id) on conflict(connection_id,deduplication_key) do nothing; return query select true,p_public_event_id; end $$;
create or replace function public.claim_pos_outbox(p_limit integer,p_lease_seconds integer default 60) returns setof public.pos_outbox_events language sql security definer set search_path=public as $$ update pos_outbox_events o set status='processing',locked_at=now(),lock_expires_at=now()+make_interval(secs=>p_lease_seconds) where o.id in(select id from pos_outbox_events where (status='pending' or(status='processing' and lock_expires_at<now())) and next_attempt_at<=now() order by created_at for update skip locked limit greatest(1,least(p_limit,100))) returning o.* $$;
revoke all on all tables in schema public from anon,authenticated; revoke all on function public.accept_private_event(text,text,text,text,text,jsonb,text,jsonb) from public; revoke all on function public.claim_pos_outbox(integer,integer) from public; grant execute on function public.accept_private_event(text,text,text,text,text,jsonb,text,jsonb) to service_role; grant execute on function public.claim_pos_outbox(integer,integer) to service_role;
commit;
-- Rollback: disable API/dispatch first; preserve financial, inbox, outbox, delivery and audit evidence. Drop functions, then tables in reverse dependency order only after retention approval.
